if (this.isBadKey(handle, null, RNPLib.ffi)) {
  continue;
}

const keyObj = {};
if (
  !this.getKeyInfoFromHandle(
    RNPLib.ffi,
    handle,
    keyObj,
    false,
    true,
    false
  )
) {
  // unexpected failure, skip
  continue;
}

if (
  keyObj.keyTrust == "r" ||
  keyObj.keyTrust == "e" ||
  (onlyIfAcceptableAsRecipientKey &&
    this.isExpiredTime(keyObj.effectiveExpiryTime))
) {
  continue;
}
